  /// harmless no-op kept for readability at call sites.
  static Future<FaCliHarness> spawn({
    String? workingDirectory,
    Map<String, String>? extraEnv,
    List<String> args = const [],
    int columns = 80,
    int rows = 24,
    int? vmServicePort,
    bool raw = true,
  }) async {
